var host = 'https://moyue.app';

function J(r){ if(typeof r==='string'){ try{return JSON.parse(r);}catch(e){ return {}; } } return r||{}; }
function detailUrlOf(bu){ return host+'/legado/detail?url='+encodeURIComponent(bu); }
function tocUrlOf(bu){ return host+'/legado/toc?url='+encodeURIComponent(bu); }

function contentUrlOf(cu){ return host+'/legado/content?url='+encodeURIComponent(cu)+'&fmt=legado'; }
function PLATNAME(p){ return String(p||'').replace(/\(VIP\)$/,''); }



function SRCLIST(j, tab){
  var out=['全部'];
  try{
    var a=(j&&j[tab])||[];
    for(var i=0;i<a.length;i++){ out.push(a[i].n + (a[i].v ? '(VIP)' : '')); }
  }catch(e){}
  if(out.length<2){ out.push('番茄'); }
  return out;
}
function SRCFG(src){
  var v={};
  try{ v=JSON.parse(src.getVariable()||'{}')||{}; }catch(e){ v={}; }
  var m=null;
  try{ m=src.getLoginInfoMap(); }catch(e){ m=null; }
  function pick(k,d){
    if(v[k]){ return String(v[k]); }
    if(m){ try{ var x=m.get(k); if(x){ return String(x); } }catch(e){} }
    return d;
  }
  var h=String(v.host||'').trim();
  if(!h && m){ try{ var lh=m.get('线路'); if(lh){ h=String(lh); } }catch(e){} }
  if(!h){ h=host; }
  if(h.indexOf('http')!=0){ h='http://'+h; }
  return { host:h, gender:pick('频道','男频'), platform:pick('平台','全部'), mode:pick('模式','小说') };
}
function SRSHOW(m, t){
  var j=this.java, s=this.source;
  var data={};
  try{ data=JSON.parse(s.getVariable()||'{}')||{}; }catch(e){ data={}; }
  data[t]=m;
  s.setVariable(JSON.stringify(data));
  j.refreshExplore();
}
function SRFLT(title, chars, def, key, size){
  return { title:title, type:'select', chars:chars, default:def,
    action:"SRSHOW(infoMap['"+title+"'],'"+key+"')",
    style:{layout_flexGrow:1, layout_flexBasisPercent:size} };
}
function SRHDR(title){
  return { title:title, url:'', style:{layout_flexGrow:1, layout_flexBasisPercent:1} };
}






function probe() {
    var java = this.java;
    var source = this.source;

    try {
        if (typeof java.showReadingBrowser == 'function') {
            return "ios";
        }
    } catch (e) {}

    try {
        if (typeof java.reLoginView == 'function') {
            return "panel";
        }
        new Packages.io.legado.kazusa.utils.TimeoutCancellationException('');
        return "panel";
    } catch (e) {}

    try {
        if (typeof source.loginUi == 'function') {
            return "browser";
        }
    } catch (e) {}

    return "panel";
}

function openReview(url, sources, ident) {
    var java = this.java;
    if (ident == null) ident = '段评';
    var rt = this.probe();
    if (rt == "panel") {
        var htmlContent = '';
        try {
            htmlContent = java.ajax(url);
        } catch (e) {}
        try {
        java.showBrowser(
            url,
            htmlContent,
            'window.java=java;',
            JSON.stringify({
                "expandedCornersRadius": 20,
                "dismissOnTouchOutside": true,
                "isDraggable": true,
                "shouldDimBackground": true,
                "backgroundDimAmount": 0.5,
                "hardwareAccelerated": true,
                "isNestedScrollingEnabled": true,
                "isGestureInsetBottomIgnored": true,
                "setFitToContents": true,
                "isHideable": true,
                "heightPercentage": 0.8
            })
        );
        } catch (e) {
            java.startBrowser(url, sources + ident);
        }
    } else {
        try { java.showReadingBrowser(url, sources + ident); return; } catch (e) {}
        java.startBrowser(url, sources + ident);
    }
}

function godOpen(u, t) { try { java.showReadingBrowser(u, t); return; } catch (e) {} try { java.startBrowser(u, t); } catch (e) {} }

function GETDID(){
  var did='';
  try{ did=String(java.deviceID()||'').trim(); }catch(e){}
  if(!did){ try{ did=String(java.androidId()||'').trim(); }catch(e){} }
  if(did){
    try{ var v=JSON.parse(source.getVariable()||'{}')||{}; if(String(v.did||'')!==did){ v.did=did; source.setVariable(JSON.stringify(v)); } }catch(e){}
    return 'yd-'+did;
  }
  var v={};
  try{ v=JSON.parse(source.getVariable()||'{}')||{}; }catch(e){ v={}; }
  if(v.did){ return 'yd-'+String(v.did); }
  did='did-'+Math.random().toString(36).slice(2)+Date.now().toString(36);
  try{ v.did=did; source.setVariable(JSON.stringify(v)); }catch(e){}
  return 'yd-'+did;
}

source.loginUrl:
function login(flag){
  if(flag===undefined){
    try{ result=JSON.parse(source.getLoginInfo()||'{}'); }catch(e){ result={}; }
  }else{
    try{ source.putLoginInfo(JSON.stringify(result)); result=JSON.parse(source.getLoginInfo()||'{}'); }catch(e){ result={}; }
  }
  var email=String(result['邮箱']||'');
  var pwd=String(result['密码']||'');
  if(!email||!pwd){ java.longToast('请填写邮箱和密码'); throw '请填写邮箱和密码'; }
  var hh='';try{hh=String((JSON.parse(source.getVariable()||'{}')||{}).host||'').trim();}catch(e){}
  if(!hh){ try{ hh=String(result['线路']||'').trim(); }catch(e){} }
  if(!hh){ hh=(typeof host!=='undefined')?host:''; }
  if(hh.indexOf('http')!=0){ hh='http://'+hh; }
  var opt=JSON.stringify({method:'POST',body:JSON.stringify({email:email,password:pwd}),headers:{'Content-Type':'application/json','X-Device-ID':GETDID()}});
  java.longToast('正在登录…');
  var resp=java.ajax(hh+'/legado/login,'+opt);
  var j=JSON.parse(resp);
  if(j && j.code==200 && j.data && j.data.token){
    var vv={};try{vv=JSON.parse(source.getVariable()||'{}');}catch(e){}
    vv.token=j.data.token; vv.host=hh;
    source.setVariable(JSON.stringify(vv));
    java.longToast('登录成功'+((j.data.user&&j.data.user.nickname)?('：'+j.data.user.nickname):''));
  }else{
    var em=(j&&j.msg)||'登录失败'; java.longToast(em); throw em;
  }
}

